function evaluateEquippedSets(char){
  const counts = new Map();
  for (const slot of ['weapon', 'headgear', 'armor', 'gloves', 'boots'] ) {
    const it = char.equipment[slot];
    if (!it) continue;
    const setDef = getEquipmentSetDef(it.family);
    counts.set(setDef.id, (counts.get(setDef.id) ?? 0) + 1);
  }
  const res= [];
  for (const set of EQUIPMENT_SETS) {
    const count = counts.get(set.id) ?? 0;
    if (count > 0) {
      res.push({
        set,
        count,
        active3: count >= 3,
        active5: count >= 5,
      });
    }
  }
  res.sort((a, b) => b.count - a.count);
  return res;
}
